import itertools

def min_inversions(binary_string, k):
    total_inversions = sum(1 for i in range(len(binary_string) - 1) for j in range(i + 1, len(binary_string)) if binary_string[i] > binary_string[j])

    operations = list(itertools.combinations(range(len(binary_string)), k))

    best_inversions = len(binary_string)
    for ops in operations:
        inversion_count = total_inversions
        for op in ops:
            reversed_op = [op_idx for op_idx in range(len(binary_string) - 1, -1, -1) if abs(op_idx - op) % 2 == 0]
            for x in reversed_op:
                for y in reversed_op:
                    if x < y:
                        count = 1
                        op1 = binary_string[x] == '1'
                        op2 = binary_string[y] == '1'
                        for i in range(x + 1, y):
                            new Op1 = binary_string[i] == '1' ^ op1
                            new Op2 = binary_string[i] == '1' ^ op2
                            if new Op1 == new Op2:
                                count += 1
                            else:
                                inversion_count -= count
                                break
        if inversion_count < best_inversions:
            best_inversions = inversion_count
    return best_inversions

