from collections import defaultdict

def bestCopy(s, n, k):
    parent = defaultdict(lambda: 0)
    times = defaultdict(lambda: 0)
    canLook = [0] * n
    canPerform = k

    # Alternate between parents
    canLook[0], canLook[-1] = 1
    canPerform -= 1

    for i in range(2, n-1, 2):
        if canLook[i-1] and canLook[i]:
            if parent[i]:
                times[i] = min(times[i], times[parent[i]])
            else:
                times[i] = min(k - times[i], canPerform)
            canLook[i] = 0

    if canLook[n-2]:
        if parent[n-2]:
            times[n-2] = min(times[n-2], times[parent[n-2]])
        else:
            times[n-2] = min(2, canPerform)
    else:
        if parent[n-2]:
            times[n-2] = min(1, times[parent[n-2]])
        else:
            times[n-2] = 0

    maxCorrect = 0
    for i in range(n):
        if times[i] == canPerform:
            maxCorrect += 1
    return maxCorrect

