        visited[u] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    if X:
                        if neighbor in X:
                            queue.append(neighbor)
                            continue
                    elif neighbor in Y:
                        queue.append(neighbor)
                        continue
                    queue.append(neighbor)
                    visited[neighbor] = True
        return len([i for i in range(n) if visited[i]])

    N = n
    X, Y = set(), set()

    for e in range(m):
        u, v = edges[e]
        if u < v:
            X.add((u, v))
        else:
            X.add((v, u))
        if u != N-1:
            Y.add((u+1, v+1))

    possible_ways = 0
    Q = deque([(N-1, set())])

    while Q:
        u, us = Q.popleft()

        if u == 0 and not X:
            possible_ways += 1
        elif u == N-1 and not Y:
            possible_ways += 1

        for neighbor in graph[u]:
