                    us.add(N-1)
                    Q.append((neighbor, us.copy()))
                elif not Y:
                    us.remove(u+1)
                    possible_ways += len(set(graph[u]) - {u-1})
                    us.add(u-1)
                    Q.append((neighbor, us.copy()))

