from collections import defaultdict

def can_construct(n, m, edges):
    # Check if it's possible to construct the new graph
    adjacency_list = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    # Check if n is even
    if n % 2 != 0:
        return -1

    # Check if the adjacency lists are matchable by labeling nodes
    matchable = True
    for u in range(1, n + 1):
        if len(adjacency_list[u]) != 2:
            return -1
        for v in adjacency_list[u]:
            if v not in adjacency_list[u]:
                matchable = False
                break

    return matchable

def construct_new_graph(n, edges):
    if not can_construct(n, len(edges), edges):
        return [-1]

    new_edges = []
    adjacency_list = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    # Initialize the new graph with n/2 new edges
    for u in range(1, n + 1, 2):
        for v in adjacency_list[u]:
            new_edges.append(f"{u} {v}")

    # Mark new edges as existing edges in the new graph
    for u, v in edges:
        adjacency_list[u].remove(v)
        if len(adjacency_list[u]) == 1:
            new_edges.append(f"{(u + 1) // 2} {u}")

    # Ensure each new edge connects to no more than two nodes
    for u, v in adjacency_list:
        if len(adjacency_list[u]) == 2:
            new_edges.append(f"{u + 1} {v}")

    # Ensure each new edge connects to no more than two nodes
    for u, v in adjacency_list:
        if len(adjacency_list[v]) == 2:
            new_edges.append(f"{u + 1} {v}")

    # Print the new edges
    return new_edges

