        queries[query] = count_changes(0, 0)

    @lru_cache(maxsize=None)
    def find_index(i, j, curr_changes, l):
        for k in range(l, n):
            curr_hash = count_changes(k, curr_changes)
            if curr_hash == queries[query]:
                return k
            curr_changes[j] -= matrix[k][j] == "a"
            if matrix[k][j] == "a":
                curr_changes[j] += 1
        return -1

    for query in range(q):
        answer.append(find_index(0, 0, 0, m))

