from math import comb

def count_rectangles(n, m, k):
    if k == 0:
        return n ** 2
    if n * m < k or k < n * m / 2:
        return 0

    dp = [[0] * (k + 1) for _ in range(min(n, m) + 1)]
    for i in range(n + 1):
        for j in range(m + 1):
            if i <= n and j <= m:
                dp[min(i, j)][i * j - 1] += comb(i * j, k) % (10 ** 9 + 7)
                dp[max(i, j) + 1][i * j - 1] -= (dp[max(i, j)][i * j - 1] // (i * j - i)) % (10 ** 9 + 7)

    result = 0
    for i in range(n + 1):
        for j in range(m + 1):
            result += dp[i][j] * (comb(j, i) * (n - i) ** (2 * j)) % (10 ** 9 + 7)
    return result % (10 ** 9 + 7)

