def flip_digit(digit):
    """Return 4 if digit is 7, and 7 if digit is 4."""
    return 4 if digit == 7 else 7

def longest_non_decreasing_subsequence(s):
    """Return the length of the longest non-decreasing subsequence in the string s."""
    stack = []
    for i, char in enumerate(s):
        while stack and flip_digit(stack[-1]) < flip_digit(char):
            stack.pop()
        stack.append(flip_digit(char))

    return len(stack)

