from itertools import product

def count_filtered_sequences(n, m, collections):
    MOD = 1000000009
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n + 1):
            if j >= collections[i - 1].count("A"):
                dp[i][j] = (dp[i-1][j] + 1) % MOD
            if j >= collections[i - 1].count("C"):
                dp[i][j] = (dp[i][j] + dp[i-1][j-collections[i-1].count("C")]) % MOD
            if j >= collections[i - 1].count("G"):
                dp[i][j] = (dp[i][j] + dp[i-1][j-collections[i-1].count("G")]) % MOD
            if j >= collections[i - 1].count("T"):
                dp[i][j] = (dp[i][j] + dp[i-1][j-collections[i-1].count("T")]) % MOD

    return sum(dp[-1]) % MOD

