def diameter_string_length(n, m):
    positions = defaultdict(list)
    edges = defaultdict(list)

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            diff = abs(i - j)
            if diff > 1:
                edges[diff].append((i, j))
            if i == j == m:
                edges[diff].append((i, j))
            if (i, j) == (m, m):
                edges[0].append((i, j))

    paths = defaultdict(int)
    for distance in range(1, n):
        for pair in edges[distance]:
            paths[pair[0]] += paths[pair[1]]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            paths[i, j] += paths[i, j, i, j]

    max_distance = -1
    for distance, occurrence in paths.items():
