def get_max_distance(graph):
    if len(graph) <= 2:
        return (n - 1) // 2, (n - 1) // 2

    max_distance = (n - 1) // 2
    adj_list = list(graph.items())

    for i in range(len(adj_list)):
        for j in range(i + 1, len(adj_list)):
            if len(adj_list[i] & adj_list[j]) > 0:
                adj_list[i] |= adj_list[j]
                adj_list.pop(j)
                break

    while len(adj_list) > 1:
        current_max = max_distance
        for i in range(len(adj_list)):
            for j in range(i + 1, len(adj_list)):
                if len(adj_list[i] & adj_list[j]) > 0:
                    adj_list[i] |= adj_list[j]
                    adj_list.pop(j)
                    break
            if len(adj_list[i]) > max_distance:
                max_distance = len(adj_list[i])
        if current_max == max_distance:
            break

    distances = [max_distance]
    for i in range(1, len(adj_list)):
        if len(adj_list[i]) > 0:
            distances.append(len(adj_list[i]))
    distances.sort()

    for i in range(len(distances) - 1):
        if distances[i + 1] == distances[i]:
            return max_distance, distances[i]

