def switch_digits(s):
    result = ""
    for digit in s:
        if digit == '4':
            result += '7'
        elif digit == '7':
            result += '4'
        else:
            result += digit
    return result

def count_longest_subsequence(n, strings):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if j == i:
                dp[j][i] = 1
            else:
                current_digit = strings[i - 1]
                adjacent_digit = strings[i - 2] if i > 1 else ''
                if adjacent_digit == '4' or adjacent_digit == '7':
                    dp[j][i] = max(dp[j][i], dp[j][i - 1])
                if current_digit == '4' or current_digit == '7':
                    dp[j][i] = max(dp[j][i], j)
    longest_subsequence = 0
    for i in range(1, n + 1):
        longest_subsequence = max(longest_subsequence, dp[i][i])
    return longest_subsequence

def process_queries(n, m, queries):
    dp = [0] * (n + 1)
    for query in queries:
        operation, l, r = query
        if operation == 'switch':
            s = switch_digits(strings[l - 1:r])
            strings[l - 1:r] = s
        elif operation == 'count':
            print(count_longest_subsequence(n, strings))
    return None

