                    if next_v not in dfs(current, next_v):
                        memo[current] = max(dfs(current, next_v), dfs(next_v, current) + B[next_v] + min(A[next_v], 0))
                    else:
                        memo[current] = memo[next_v] + B[next_v]
                    break
                else:
