from itertools import combinations, chain

def generate_sequences(sequence, num_of_sequences, length):
    if not sequence:
        return [[] for _ in range(num_of_sequences)]
    elif len(sequence) == 1:
        return [[seq] for seq in chain.from_iterable(combinations(sequence, length))]

    sequences = []
    for start in range(length + 1):
        for end in range(length, start - 1, -1):
            for combo in combinations(sequence, start):
                if (start, end) not in combinations(chain.from_iterable(combo), length - end):
                    sequences.append([seq+(sequence[(i + start):(i + end) - (start - 1)],) for seq in chain.from_iterable(combinations(combo, start))])
            for combo in combinations(sequence, start - 1):
                for combo2 in combinations(combo, length - end):
                    sequences.append([seq+(sequence[(i + start):(i + end) - 1],) for seq in chain.from_iterable(combinations(combo2, start - 1))])

    return sequences[:num_of_sequences]

