from functools import lru_cache
from typing import List

def count_sequences(n: int, k: int, seqs: List[str]) -> int:
    MOD = 1000000009
    dp = [0] * (n + 1)
    dp[0] = 1

    for j in range(2, n + 1):
        dp[j] = 0
        for i in range(j, n + 1):
            dp[j] += dp[i][j - 1]
            dp[j] %= MOD

            # If we have the length of seqs
            if i - j + 1 <= len(seqs):
                target = seqs[i - j + 1 - 1]
                count = min(k, len(target) + i - j)
                dp[j] += dp[j - count][j - 1] * count
                dp[j] %= MOD

    return dp[n]

class SequenceFilter:
    def num_sequences(self, n: int, k: int, seqs: List[str]) -> int:
        MOD = 1000000009

        @lru_cache(None)
        def dp(i, position_of_sequences, length):
            if position_of_sequences == len(seqs):
                return 1 if i == n else 0
            if i > n:
                return 0
            return dp(i + 1, position_of_sequences, length + 1) + dp(i + length, position_of_sequences + 1, 1)

        dp.cache_clear()  # Clear the cache before use
        return dp(1, 0, 0) % MOD
