        self.n = n
        self.tree = [0] * (2*n+1)
        self.lazy = [0] * (2*n+1)
        self.length = n
        self.data = data

        if len(data) > 0:
            self.build(1, 1, self.n)

    def build(self, root, start, end):
        if start == end:
            self.tree[root] = self.data[start]
            return
        mid = (start + end) // 2
        left = root * 2
        right = root * 2 + 1
        self.build(left, start, mid)
        self.build(right, mid+1, end)
        self.tree[root] = max(self.tree[left], self.tree[right])

    def query(self, root, start, end, l, r):
        if l <= start and end <= r:
            return self.tree[root]
        elif end < l or start > r:
            return 0
        else:
            mid = (start + end) // 2
            return max(self.query(root*2, start, mid, l, r),
                       self.query(root*2+1, mid+1, end, l, r))

    def update_lazy(self, root, start, end, value, left, right):
        if left <= start and end <= right:
            self.tree[root] = value
            self.lazy[root] = value
            return
        elif end < left or start > right:
            return
        else:
            mid = (start + end) // 2
            left = left * 2
            right = right * 2 + 1
            self.update_lazy(left, start, mid, value, left, right)
            self.update_lazy(right, mid+1, end, value, left, right)
            self.tree[root] = max(self.tree[left], self.tree[right])
            self.lazy[root] = 0

    def update(self, root, start, end, l, r, val):
        if l <= start and end <= r:
            self.update_lazy(root, start, end, val, l, r)
            return
        elif end < l or start > r:
            return
        else:
            mid = (start + end) // 2
            left = root * 2
            right = root * 2 + 1
            self.update(left, start, mid, l, r, val)
            self.update(right, mid+1, end, l, r, val)
            self.tree[root] = max(self.tree[left], self.tree[right])

    def updateTree(self, left, right, val):
        self.update(1, 1, self.n, left, right, val)

    def countQueries(self, left, right):
        return self.query(1, 1, self.n, left, right)

T = int(sys.stdin.readline().rstrip())

for t in range(T):
    n, m = map(int, sys.stdin.readline().rstrip().split())
    digits = sys.stdin.readline().rstrip()
    tree = LazySegmentTree(n, digits)
    queries = []
    for q in range(m):
        type = int(sys.stdin.readline().rstrip())
        if type == 1:
            l, r = map(int, sys.stdin.readline().rstrip().split())
