    queries.sort(key=lambda x: x[0])
    l = len(digits)*2-1  # Delay the update by due to lazy propagation
    for (type, length) in queries:
        # Get all val at some pos due to type==1
        if type == 1:
            for l, r in queries:
                query = (l, r)
                tree.updateTree(l-l, r-l, r-l-1)
        # Update to update the lazy values to the bound get after step
        if length > tree.length:
            for query in queries:
                if query in queries:
                    step = tree.query(1, 1, n, query[0]-l, query[1]-l)
                    tree.updateTree(query[0]-l, query[1]-l, step+1)

    results = []
    for (_, l) in queries:
        result = tree.countQueries(l, l)
        results.append(result)
    print(*results, sep='\n')
