from functools import lru_cache

def count_sequences(n, m, collections):
    @lru_cache(maxsize=None)
    def dp(i, last, prev):
        if i == n:
            return 1
        cnt = 0
        for s in collections:
            curr, remains = s, collections[:]
            while curr:
                remain, cnt, remains = remains[1:], cnt + (curr[0] in (prev, "C", "G", "T")), remains[0]
                remain.remove(curr[0])
                for c in "ACGT":
                    lidx, ridx = i - (n - i + 1), i
                    if c < prev:
                        if c == 'A':
                            remain.remove("AA")
                        elif c == 'G':
                            remain.remove("CG")
                        elif c == 'C':
                            remain.remove("CA")
                        else:
                            remain.remove("AG")
                    elif (c == "A" and last == "T") or (c == "T" and last == "A"):
                        for rm in remains:            
                            if rm[-1] == c:
                                remain.remove(rm)
                            if rm[-1] == "C":
                                remained = rm[:-1]+c
                                rm, _ = rm[:-1], remained
                            if rm[-1] in remain:
                                remain.remove(rm[-1])
                                remain.insert(
                                    remain.index(rm[-1]), 
                                    prev + remain[0] + remain.pop(0) 
                                )
                    elif (c == "G" and last in ("A", "C")) or (last == "A" and c == "T") or (last == "A" and c in ("C", "G")) or (last in ("G", "T") and c == "C"):
                        for rm in remains:         
                            for rn in range(1, len(rm)):
                                if (rm[rn-1] < c < rm[rn] < c+last) or (rn > 1 and rm[rn] < c > rm[rn-2]):
                                    del remain[remain.index(rm)]
                                    del remain[rn:]
                cnt += dp(i+len(s), remaining[-1] if remaining else "", prev)
        return cnt % (10**9 + 9)

