from heapq import heappop, heappush
from collections import defaultdict

def maximize_questions(n, p, k, q1, q2):
    graph = defaultdict(list)
    for i in range(1, n + 1):
        graph[i].append(i)

    answer_sheet = f"{q1} {q2}"

    for i in answer_sheet.split():
        for j in graph[int(i)]:
            to_add = q2 - k + 1 + 1
            graph[j].append(j)
            if to_add:
                graph[j].append(j)
                heapq.heappush(graph[j], (graph[int(i)][-1] - len(graph[int(i)]) + 1, -len(graph[int(i)])))

        for graph_i in graph[j]:
            graph[i].append(graph_i)
            if graph_i < 0 and graph_i // abs(graph_i) > -1:
                heapq.heappush(graph[i], (graph_i - max(len(graph[j]) % k, 1) + k, k - len(graph[j])))

    result = 0
    q = []
    for item in graph[p]:
        while q and q[0][0] <= item:
            result += heappop(q)[1]
        if not q or q[0][1] < item:
            result += k
        else:
            result += item
        heappush(q, (item - 1, result))

    return result
