def build_graph(n, s):
    g = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if (s[i] == s[j] or abs(i - j) == 1):
                g[i].append(j)
                g[j].append(i)
    return g

def bfs(g, start, end, visited):
    queue = [start]
    dist = {start: 0}
    prev = {start: -1}
    while queue:
        curr = queue.pop(0)
        if curr == end:
            break
        for neighbor in g[curr]:
            if neighbor not in dist or dist[curr] + 1 < dist[neighbor]:
                queue.append(neighbor)
                dist[neighbor] = dist[curr] + 1
                prev[neighbor] = curr
    return dist, prev

def diameter_and_count(dists, prev, n):
    max_dist = float('-inf')
    count = 0
    for i in range(1, n - 1):
        if dists[prev[i]] + 1 == dists[i]:
            count += 1
    for i in range(n - 1):
        for j in range(i):
            if dists[prev[i]] + 1 == dists[curr[i]] and dists[j] + 1 == dists[curr[i]]:
                max_dist = max(max_dist, dists[prev[i]] + 1)
    return max_dist, count

def solve_problem(n, s):
    graph = build_graph(n, s)
    dists, prev = bfs(graph, 0, len(s) - 1, {})
    max_dist, count = diameter_and_count(dists, prev, n)
    return max_dist, count

