def count_rectangles(n, m, k, grid):
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp_k = [[0] * (m) for _ in range(k + 1)]

    # Count the number of cells containing '1' for all k
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '1':
                for x in range(i):
                    for y in range(j):
                        dp[(x + 1) % (i + 1)][(y + 1) % (j + 1)] += 1

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, m):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1] + dp[(i + j) // 2][max(j - 1 - (i - j), -(n + 1))]

    # Fill the dp_k array
    for j in range(1, m):
        for i in range(1, n):
            dp_k[i][j] = dp_k[i - 1][j] + dp[(i + 3j) // 2][max(j - 1 - (i - j), -(n + 1))] - dp[(i - 1 + j] // 2][max(j - 1 - ((i + 1 - j) % 2), -(n + 1))]

    # Result
    result = 0
    for i in range(1, n + 1 - k):
        for j in range(1, m + 1):
            if dp[i + k - 1][j] - dp[i - 1 + k - 1][j] == dp_k[i - 1][0] / 2:
                result += dp[i][j]
    return result
