from collections import defaultdict

def construct_new_graph():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    new_graph = [[-1] * n for _ in range(n)]

    for u, adj_u in graph.items():
        for v, adj_v in graph.items():
            if u != v and (len(adj_u) + len(adj_v)) % 2 == 0:
                continue
            new_u, new_v = 1, 1
            found_new = False
            for w in adj_v:
                if found_new and new_v > u:
                    new_v = -1 * float('inf')
                if w in adj_u:
                    if w > 0:
                        new_u += 1
                    else:
                        if u > 0:
                            new_v += 1
                        else:
                            new_u -= 1
                elif w < 0:
                    if u > 0:
                        new_v -= 1
                    else:
                        new_u += 1
                new_graph[u][new_u] = new_v
                new_graph[v][new_v] = new_u
                found_new = True
            if not found_new:
                return -1

    return '\n'.join([' '.join(map(str, row)) for row in new_graph])

if __name__ == '__main__':
    print(construct_new_graph())
