def max_empty_square_size(parking_lot, cars):
    n, m = len(parking_lot), len(parking_lot[0])
    # Mark empty spots in parking_lot
    for row in parking_lot:
        for i, cell in enumerate(row):
            if cell == '.':
                row[i] = 0

    # Mark taken spots in parking_lot
    for y in range(m):
        for x in range(n):
            if parking_lot[x][y] == 'X':
                parking_lot[x][y] = 0

    # Add a column to each row to mark the left most empty spot
    for row in parking_lot:
        for j, cell in enumerate(row):
            if cell == 0:
                row[j] = j

    result = []
    for c in cars:
        # Find the maximum square of empty spots reaching position of car
        max_size = 0
        for y in range(c[1], m):
            size = 1
            for x in range(c[0], n):
                if parking_lot[x][y] != 0:
                    size += 1
                    parking_lot[x][y] = 0
                if size > max_size:
                    max_size = size
        result.append(max_size)

    return result

