from collections import defaultdict

def count_rectangles(n, m, k, grid):
    dp = defaultdict(int)
    dp[0] = 1  # Base case: 1x1 rectangles are just 1


    for row in grid:
        for i in range(len(row)):
            number = -1
            for j in range(len(row) - i):
                number += int(row[j])
                if dp[number]:
                    dp[k - number] += dp[number]
                    dp[k - number] += m - j
            num_ones = sum(map(int, row))
            for i in range(1, min(k, num_ones) + 1):
                if dp[i]:
                    dp[k - i] += dp[i]
                    dp[k - i] += (m - j) * i
            if i == k:
                total_rectangles = num_ones * (num_ones - 1) // 2
            elif (k - i) * (i - 1) <= dp[i]:
                total_rectangles = (k - i) * (i - 1)
            else:
                total_rectangles = dp[k - i]
            if dp[k]:
                dp[k] -= dp[i]
                dp[k] += total_rectangles
            dp[k] += total_rectangles

    return dp[k]

n, m, k = map(int, input().split())
grid = [input() for _ in range(n)]
result = count_rectangles(n, m, k, grid)
print(result)
